  ('e7000000-0000-4000-8000-000000000058', null, 'Color A Smile', 'A nonprofit that sends cheerful hand-colored drawings to seniors, troops, and anyone needing a smile - color from home and mail them in.', 'https://colorasmile.org', 'https://www.google.com/s2/favicons?domain=colorasmile.org&sz=128', 'community', array['no experience needed', 'family friendly'], true, false, 13, 'United States', null, null, true, true, 'ongoing', false),
  ('e7000000-0000-4000-8000-000000000059', null, 'The World Needs More Love Letters', 'A nonprofit that mobilizes volunteers to write and send bundles of handwritten letters to strangers going through hard times.', 'https://www.moreloveletters.com', 'https://www.google.com/s2/favicons?domain=www.moreloveletters.com&sz=128', 'community', array['no experience needed', 'writing or editing'], true, false, 13, 'United States', null, null, true, true, 'ongoing', false),
  ('e7000000-0000-4000-8000-000000000062', null, 'Create the Good', 'AARP''s volunteering hub, with do-it-yourself projects and remote opportunities you can take on in an hour or over time.', 'https://createthegood.aarp.org', 'https://www.google.com/s2/favicons?domain=aarp.org&sz=128', 'community', array['no experience needed', 'good for solo volunteers'], true, false, 16, 'United States', null, null, true, true, 'ongoing', false),
  ('e7000000-0000-4000-8000-000000000064', null, 'Vote Forward', 'A nonpartisan nonprofit whose volunteers write personalized letters encouraging fellow citizens to register and vote.', 'https://votefwd.org', 'https://www.google.com/s2/favicons?domain=votefwd.org&sz=128', 'community', array['no experience needed', 'writing or editing'], true, false, 16, 'United States', null, null, true, true, 'ongoing', false),
  ('e7000000-0000-4000-8000-000000000065', null, 'Postcards to Voters', 'A grassroots effort where volunteers hand-write friendly postcards reminding voters about upcoming elections.', 'https://postcardstovoters.org', 'https://www.google.com/s2/favicons?domain=postcardstovoters.org&sz=128', 'community', array['no experience needed', 'writing or editing'], true, false, 16, 'United States', null, null, true, true, 'ongoing', false),
  ('e7000000-0000-4000-8000-000000000066', null, 'Idealist', 'One of the largest hubs for nonprofit jobs, internships, and volunteering, with thousands of remote opportunities to browse.', 'https://www.idealist.org', 'https://www.google.com/s2/favicons?domain=www.idealist.org&sz=128', 'community', array['no experience needed', 'leadership role'], true, true, 16, 'Global', null, null, true, true, 'ongoing', false),
  ('e7000000-0000-4000-8000-000000000067', null, 'Points of Light', 'The world''s largest organization dedicated to volunteer service, whose Engage platform lists virtual ways to help near and far.', 'https://www.pointsoflight.org', 'https://www.google.com/s2/favicons?domain=www.pointsoflight.org&sz=128', 'community', array['no experience needed', 'good for solo volunteers'], true, false, 16, 'United States', null, null, true, true, 'ongoing', false),
  ('e7000000-0000-4000-8000-000000000068', null, 'JustServe', 'A free service that connects volunteers with community needs and projects, including many that can be done online.', 'https://www.justserve.org', 'https://www.google.com/s2/favicons?domain=www.justserve.org&sz=128', 'community', array['no experience needed', 'family friendly'], true, true, 13, 'Global', null, null, true, true, 'ongoing', false),
  -- SENIORS & INTERGENERATIONAL (seniors)
  ('e7000000-0000-4000-8000-000000000060', null, 'Cyber-Seniors', 'A nonprofit where young volunteers teach older adults how to use technology, connecting generations through free online mentoring.', 'https://cyberseniors.org', 'https://www.google.com/s2/favicons?domain=cyberseniors.org&sz=128', 'seniors', array['teaching or tutoring', 'tech skills useful'], true, false, 14, 'United States', null, null, true, true, 'ongoing', false),
  ('e7000000-0000-4000-8000-000000000061', null, 'Big & Mini', 'A nonprofit that matches younger and older people for friendly video calls, easing isolation across the generations.', 'https://bigandmini.org', 'https://www.google.com/s2/favicons?domain=bigandmini.org&sz=128', 'seniors', array['no experience needed', 'great for making friends'], true, false, 13, 'United States', null, null, true, true, 'ongoing', false),
  -- VETERANS (veterans)
  ('e7000000-0000-4000-8000-000000000063', null, 'Veterans History Project', 'A Library of Congress program that collects and preserves veterans'' stories, with volunteers interviewing and documenting their service.', 'https://www.loc.gov/programs/veterans-history-project/', 'https://www.google.com/s2/favicons?domain=www.loc.gov&sz=128', 'veterans', array['no experience needed', 'public speaking'], true, false, 15, 'United States', null, null, true, true, 'ongoing', false)
on conflict (id) do nothing;

insert into public.opportunities
  (id, org_id, title, category, description, tags, min_age, remote, is_online, is_ongoing,
   hours_estimate, signup_link, external_url, starts_at, city, state)
values
  ('e8000000-0000-4000-8000-000000000001', 'e7000000-0000-4000-8000-000000000001', 'Find a Citizen-Science Project', 'tech', 'SciStarter is a giant catalog of real research projects that need everyday people, and you can filter by topic, age, and how you want to help. Pick something that excites you - counting fireflies, classifying photos, measuring water quality - and follow the link to start contributing. It is the easiest way to find citizen science that fits you, with no experience needed.', array['no experience needed', 'good for solo volunteers'], 13, true, true, true, 'Flexible', 'https://scistarter.org', 'https://scistarter.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000002', 'e7000000-0000-4000-8000-000000000002', 'Donate Your Computer''s Spare Power', 'tech', 'Folding@home turns your idle computer into a tiny supercomputer for disease research on cancer, Alzheimer''s, and more. You install a free program, and when you are not using your machine it quietly runs simulations for scientists. It is a set-it-and-forget-it way to contribute to real research from home.', array['no experience needed', 'tech skills useful'], 13, true, true, true, 'Flexible', 'https://foldingathome.org', 'https://foldingathome.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000003', 'e7000000-0000-4000-8000-000000000003', 'Power Research While You Sleep', 'tech', 'World Community Grid lets you donate your device''s unused computing time to major health and environmental research. Download the free app, and your phone or laptop runs research calculations in the background when it is charging or idle. Thousands of volunteers together create the equivalent of a massive research computer.', array['no experience needed', 'tech skills useful'], 13, true, true, true, 'Flexible', 'https://www.worldcommunitygrid.org', 'https://www.worldcommunitygrid.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000004', 'e7000000-0000-4000-8000-000000000004', 'Map Places for Disaster Relief', 'tech', 'Humanitarian OpenStreetMap volunteers trace roads, buildings, and rivers from satellite images so aid organizations have maps where none existed. You pick a mapping task, follow a short tutorial, and your work helps responders reach people after floods, earthquakes, and disease outbreaks. No mapping background is needed - just a computer and a bit of care.', array['no experience needed', 'training provided'], 16, true, true, true, 'Flexible', 'https://www.hotosm.org', 'https://www.hotosm.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000005', 'e7000000-0000-4000-8000-000000000005', 'Volunteer Your Mapping Skills', 'tech', 'GISCorps places volunteers with mapping and geographic-information-system skills on humanitarian, health, and disaster projects around the world. If you have GIS experience or are studying it, you can take on remote assignments that put your skills to real use. It is a standout way for students and professionals to give back with a specialized talent.', array['skilled volunteers wanted', 'tech skills useful'], 18, true, true, true, 'Flexible', 'https://www.giscorps.org', 'https://www.giscorps.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000006', 'e7000000-0000-4000-8000-000000000006', 'Play a Puzzle for Science', 'tech', 'Foldit turns protein science into a game anyone can play, and the best solutions from players have actually helped researchers. You fold and twist 3D proteins to solve puzzles, learning as you go with built-in tutorials. It is a genuinely fun way to contribute to biochemistry research from your couch.', array['no experience needed', 'good for solo volunteers'], 13, true, true, true, 'Flexible', 'https://fold.it', 'https://fold.it', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000007', 'e7000000-0000-4000-8000-000000000007', 'Design RNA in a Game', 'tech', 'Eterna is a browser game where you solve RNA-folding puzzles, and scientists build the top designs in real labs. You start with tutorials and work up to challenges that push actual research forward. If you like puzzles and want your play to matter, this is a rewarding way to help.', array['no experience needed', 'good for solo volunteers'], 13, true, true, true, 'Flexible', 'https://eternagame.org', 'https://eternagame.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000008', 'e7000000-0000-4000-8000-000000000008', 'Improve the World Map', 'tech', 'OpenStreetMap is a free map of the world that anyone can edit, and your local knowledge makes it better for everyone. You can add missing sidewalks, trails, shops, and buildings you know, right from a web browser. It is used by charities, researchers, and apps everywhere, so your edits genuinely get used.', array['no experience needed', 'tech skills useful'], 13, true, true, true, 'Flexible', 'https://www.openstreetmap.org', 'https://www.openstreetmap.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000011', 'e7000000-0000-4000-8000-000000000011', 'Transcribe Historic Ship Logs', 'tech', 'Old Weather volunteers read and transcribe the handwritten logs of old ships, recovering weather records that help scientists understand our changing climate. You also uncover human stories of life at sea along the way. Tasks are bite-sized, guidance is provided, and every page you finish adds real data to research.', array['no experience needed', 'writing or editing'], 13, true, true, true, 'Flexible', 'https://www.oldweather.org', 'https://www.oldweather.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000018', 'e7000000-0000-4000-8000-000000000018', 'Use Data Skills for Good', 'tech', 'DataKind connects volunteers who know statistics, data science, or machine learning with nonprofits solving big social problems. You might clean data, build a model, or help a cause make sense of its information, all remotely. It is a meaningful way for data-minded students and professionals to put their skills to work.', array['skilled volunteers wanted', 'tech skills useful'], 18, true, true, true, 'Flexible', 'https://www.datakind.org', 'https://www.datakind.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000069', 'e7000000-0000-4000-8000-000000000069', 'Build Civic Tech', 'tech', 'Code for America and its volunteer network build digital tools that make public services easier to use, from benefits applications to court reminders. Volunteers with design, coding, data, or research skills can join projects that help real people. It is a great fit if you want to use tech skills to improve your community.', array['skilled volunteers wanted', 'tech skills useful'], 18, true, true, true, 'Flexible', 'https://codeforamerica.org', 'https://codeforamerica.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000009', 'e7000000-0000-4000-8000-000000000009', 'Share Free Media', 'art', 'Wikimedia Commons is the free media library that powers Wikipedia, and it grows when volunteers upload and organize photos, sound, and video. You can contribute your own photos of places, plants, or events, or help sort and tag existing files. Your work becomes a resource the whole world can freely reuse.', array['no experience needed', 'photography'], 13, true, true, true, 'Flexible', 'https://commons.wikimedia.org', 'https://commons.wikimedia.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000010', 'e7000000-0000-4000-8000-000000000010', 'Transcribe for Museums', 'art', 'DigiVol volunteers turn museum treasures - specimen labels, field diaries, and expedition notes - into text that scientists can search and study. You choose an expedition, read the images, and type what you see, with clear guidance throughout. It opens up natural-history collections from Australia and beyond, all from your keyboard.', array['no experience needed', 'writing or editing'], 13, true, true, true, 'Flexible', 'https://digivol.ala.org.au', 'https://digivol.ala.org.au', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000013', 'e7000000-0000-4000-8000-000000000013', 'Transcribe American History', 'art', 'By the People invites you to transcribe letters, diaries, and documents from the Library of Congress so they become searchable for everyone. You read a scanned page, type what it says, and review others'' work, with no account fees or special skills required. It is a quiet, satisfying way to make history more accessible.', array['no experience needed', 'writing or editing'], 13, true, true, true, 'Flexible', 'https://crowd.loc.gov', 'https://crowd.loc.gov', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000014', 'e7000000-0000-4000-8000-000000000014', 'Tag and Transcribe Records', 'education', 'The National Archives Citizen Archivist program lets you add tags and transcriptions to the nation''s historical records, from war documents to old photographs. Your contributions help millions of people find and understand these records online. Pick a mission that interests you and start with just a few minutes.', array['no experience needed', 'writing or editing'], 13, true, true, true, 'Flexible', 'https://www.archives.gov/citizen-archivist', 'https://www.archives.gov/citizen-archivist', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000015', 'e7000000-0000-4000-8000-000000000015', 'Index Historical Records', 'community', 'FamilySearch volunteers read scanned historical documents and type key details so families everywhere can discover their ancestors for free. You work at your own pace on records like census pages and church registers, with training built in. Every batch you index helps someone connect with their family story.', array['no experience needed', 'writing or editing'], 13, true, true, true, 'Flexible', 'https://www.familysearch.org/getinvolved/', 'https://www.familysearch.org/getinvolved/', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000016', 'e7000000-0000-4000-8000-000000000016', 'Help Save a Language', 'education', 'Wikitongues volunteers record videos of people speaking their native languages and help build free tools to keep those languages alive. If you speak a second language or know someone who does, you can submit a recording or help transcribe and organize the archive. It is a powerful way to protect the world''s linguistic diversity.', array['bilingual helpful', 'creative work'], 16, true, true, true, 'Flexible', 'https://wikitongues.org/volunteer/', 'https://wikitongues.org/volunteer/', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000017', 'e7000000-0000-4000-8000-000000000017', 'Transcribe Runaway Ads', 'education', 'Freedom on the Move asks volunteers to transcribe and describe historical newspaper ads about people who escaped slavery, building a database that honors their lives. You read a short ad, type it up, and answer a few questions about it. It is meaningful, focused work that supports research and remembrance.', array['no experience needed', 'writing or editing'], 13, true, true, true, 'Flexible', 'https://freedomonthemove.org', 'https://freedomonthemove.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000023', 'e7000000-0000-4000-8000-000000000023', 'Help Digitize Free Books', 'education', 'Project Gutenberg offers tens of thousands of free e-books, and volunteers keep the library growing by helping digitize, format, and check public-domain works. You can pitch in on tasks that fit your skills, from reading to light coding. It is a great fit if you love books and want to keep them free for everyone.', array['no experience needed', 'writing or editing'], 13, true, true, true, 'Flexible', 'https://www.gutenberg.org', 'https://www.gutenberg.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000025', 'e7000000-0000-4000-8000-000000000025', 'Log Bird Sightings', 'animals', 'eBird turns your birdwatching into science - every checklist you submit helps researchers track bird populations and migration around the globe. You note the birds you see and where, using a free app or the website, and the data feeds hundreds of studies. It is beginner-friendly and turns any walk into a contribution.', array['no experience needed', 'good for solo volunteers'], 13, true, true, true, 'Flexible', 'https://ebird.org', 'https://ebird.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000026', 'e7000000-0000-4000-8000-000000000026', 'Count Birds at Your Feeder', 'animals', 'Project FeederWatch has you count the birds that visit your feeder over the winter and report them to the Cornell Lab of Ornithology. You watch on your own schedule, jot down what you see, and your counts help scientists spot changes in bird populations. It is a cozy, low-key way to do real science from a window.', array['no experience needed', 'family friendly'], 13, true, true, true, 'Flexible', 'https://feederwatch.org', 'https://feederwatch.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000027', 'e7000000-0000-4000-8000-000000000027', 'Monitor a Bird Nest', 'animals', 'NestWatch teaches you how to find and safely check bird nests, then record what you observe so scientists can learn how birds are doing. A quick free course shows you the simple rules, and then you report your nests online. It is a hands-on outdoor project that adds to a national research database.', array['no experience needed', 'outdoors'], 13, true, true, true, 'Flexible', 'https://nestwatch.org', 'https://nestwatch.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000028', 'e7000000-0000-4000-8000-000000000028', 'Join the Bird Count', 'animals', 'The Great Backyard Bird Count is a global event each February where you spend as little as 15 minutes counting birds and reporting them online. Anyone anywhere can join, and together the counts create a real-time snapshot of bird life worldwide. It is a perfect first citizen-science project for families and classes.', array['no experience needed', 'family friendly'], 13, true, true, true, '15+ min', 'https://www.birdcount.org', 'https://www.birdcount.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000029', 'e7000000-0000-4000-8000-000000000029', 'Tag Monarch Butterflies', 'animals', 'Monarch Watch engages volunteers to tag migrating monarch butterflies and plant milkweed habitat, helping track one of nature''s great journeys. You can order tags, rear and release monarchs, or create a waystation garden, with clear instructions provided. It is a beautiful way to help a beloved species.', array['no experience needed', 'outdoors'], 13, true, true, true, 'Flexible', 'https://monarchwatch.org', 'https://monarchwatch.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000030', 'e7000000-0000-4000-8000-000000000030', 'Photograph Bumble Bees', 'animals', 'Bumble Bee Watch asks volunteers to snap photos of bumble bees and upload them so experts can identify the species and track which ones are declining. You just need a camera or phone and a little patience in a garden or park. Your sightings directly support pollinator conservation.', array['no experience needed', 'photography'], 13, true, true, true, 'Flexible', 'https://www.bumblebeewatch.org', 'https://www.bumblebeewatch.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000031', 'e7000000-0000-4000-8000-000000000031', 'Listen for Frogs', 'animals', 'FrogWatch USA trains volunteers to recognize the calls of local frogs and toads, then report what they hear on spring and summer evenings. A short training gets you started, and your reports help scientists understand wetland health. It is a peaceful way to spend an evening outdoors doing science.', array['no experience needed', 'training provided'], 13, true, true, true, 'Flexible', 'https://www.aza.org/frogwatch', 'https://www.aza.org/frogwatch', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000032', 'e7000000-0000-4000-8000-000000000032', 'Join a Bird Community Count', 'animals', 'The National Audubon Society runs community-science programs like the Christmas Bird Count and Climate Watch that anyone can join. You count birds in your area and report them, adding to more than a century of conservation data. It is a welcoming way to help protect birds and the places they need.', array['no experience needed', 'family friendly'], 13, true, true, true, 'Flexible', 'https://www.audubon.org/community-science', 'https://www.audubon.org/community-science', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000033', 'e7000000-0000-4000-8000-000000000033', 'Track Spring Migration', 'environment', 'Journey North volunteers report the first monarchs, hummingbirds, robins, and blooms they see, helping map the wave of spring across the continent. You submit quick sightings online, and the data becomes maps that scientists and classrooms use. It is an easy, joyful way to notice the seasons and contribute.', array['no experience needed', 'family friendly'], 13, true, true, true, 'Flexible', 'https://journeynorth.org', 'https://journeynorth.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000034', 'e7000000-0000-4000-8000-000000000034', 'Observe Plants and Animals', 'environment', 'Nature''s Notebook has you watch a plant or animal near you and record when it leafs out, flowers, or migrates, building a long-term record of nature''s timing. You pick a spot, make regular observations, and enter them online. Your notes help researchers understand how climate is shifting the seasons.', array['no experience needed', 'outdoors'], 13, true, true, true, 'Flexible', 'https://www.usanpn.org/natures_notebook', 'https://www.usanpn.org/natures_notebook', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000035', 'e7000000-0000-4000-8000-000000000035', 'Measure Light Pollution', 'environment', 'Globe at Night asks you to step outside, count how many stars you can see in a constellation, and report it to map light pollution worldwide. It takes just a few minutes on a clear night and needs no equipment. Your observations help scientists and cities understand and reduce the loss of dark skies.', array['no experience needed', 'good for solo volunteers'], 13, true, true, true, 'A few min', 'https://globeatnight.org', 'https://globeatnight.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000036', 'e7000000-0000-4000-8000-000000000036', 'Report Rain and Snow', 'environment', 'CoCoRaHS volunteers measure precipitation with a simple backyard rain gauge and report it daily, filling gaps in the weather record. A short training and an inexpensive gauge are all you need to join this nationwide network. Your readings are used by meteorologists, farmers, and researchers every day.', array['no experience needed', 'recurring'], 13, true, true, true, 'A few min / day', 'https://www.cocorahs.org', 'https://www.cocorahs.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000037', 'e7000000-0000-4000-8000-000000000037', 'Watch Plants Through the Seasons', 'environment', 'Budburst volunteers observe how plants change with the seasons and share what they see to help scientists study climate change. You can track a plant in your yard, a park, or even a houseplant, and log your observations online. It is a gentle, ongoing way to connect with nature and contribute data.', array['no experience needed', 'outdoors'], 13, true, true, true, 'Flexible', 'https://budburst.org', 'https://budburst.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000038', 'e7000000-0000-4000-8000-000000000038', 'Log Litter You Find', 'environment', 'Marine Debris Tracker lets you record the litter you pick up on a beach, trail, or street, adding to an open dataset that scientists use to fight plastic pollution. You just open the app, log what you collect, and your data helps researchers and communities target cleanups. It turns any cleanup into science.', array['no experience needed', 'outdoors'], 13, true, true, true, 'Flexible', 'https://debristracker.org', 'https://debristracker.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000039', 'e7000000-0000-4000-8000-000000000039', 'Map the World''s Litter', 'environment', 'Litterati is a global community that photographs and tags litter, building a map that drives cleanups, better products, and smarter policy. You snap a picture of a piece of litter, tag it, and pick it up, and your data joins millions of others. It is a simple habit that adds up to real change.', array['no experience needed', 'photography'], 13, true, true, true, 'Flexible', 'https://litterati.org', 'https://litterati.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000040', 'e7000000-0000-4000-8000-000000000040', 'Join a Research Project', 'environment', 'CitSci hosts thousands of citizen-science projects on everything from water quality to wildlife, and helps you find one to join or even start your own. You sign up, pick a project, and follow its instructions to collect and submit data. It is a flexible home base for anyone who wants to do hands-on science.', array['no experience needed', 'good for solo volunteers'], 13, true, true, true, 'Flexible', 'https://citsci.org', 'https://citsci.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000012', 'e7000000-0000-4000-8000-000000000012', 'Hunt Clogs in Brain Images', 'medicine', 'Stall Catchers is an online game where you watch short movies of blood vessels in mouse brains and mark where blood flow is stalled, feeding real Alzheimer''s research. A quick tutorial gets you playing, and your answers are combined with others for accuracy. It is a genuinely fun way to speed up science.', array['no experience needed', 'good for solo volunteers'], 13, true, true, true, 'Flexible', 'https://stallcatchers.com', 'https://stallcatchers.com', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000051', 'e7000000-0000-4000-8000-000000000051', 'Become a Trained Listener', 'medicine', '7 Cups trains volunteers to be active listeners who offer free, caring, anonymous support to people going through a tough time. You complete an online training, then chat with people who just need to be heard, all on your own schedule. It is a meaningful way to support mental health from home.', array['training provided', 'recurring'], 15, true, true, true, 'Flexible', 'https://www.7cups.com/volunteer/', 'https://www.7cups.com/volunteer/', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000052', 'e7000000-0000-4000-8000-000000000052', 'Support People in Distress', 'medicine', 'Samaritans volunteers provide a listening ear to people who are struggling to cope, offering support without judgment. Volunteers receive thorough training and ongoing support, and some roles can be done remotely. It is a serious, deeply meaningful commitment for those 18 and older who want to be there for others.', array['training provided', 'recurring'], 18, true, true, true, 'Ongoing', 'https://www.samaritans.org/support-us/volunteer/', 'https://www.samaritans.org/support-us/volunteer/', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000053', 'e7000000-0000-4000-8000-000000000053', 'Answer the Peer Hotline', 'medicine', 'Trans Lifeline is a hotline run by and for transgender people, and trained volunteer operators offer peer support to callers who need it. You complete training before taking calls and are supported throughout your shifts. It is a powerful role for adults who want to show up for the trans community.', array['training provided', 'LGBTQ+ friendly'], 18, true, true, true, 'Ongoing', 'https://translifeline.org/volunteer/', 'https://translifeline.org/volunteer/', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000054', 'e7000000-0000-4000-8000-000000000054', 'Chat with People in Crisis', 'medicine', 'IMAlive is an online crisis network where trained volunteers chat with people in emotional crisis in real time, right from home. You go through training and certification first, then take chats on a schedule that works for you. It is a serious commitment and one of the most impactful ways to help.', array['training provided', 'recurring'], 18, true, true, true, 'Ongoing', 'https://www.imalive.org/volunteer', 'https://www.imalive.org/volunteer', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000055', 'e7000000-0000-4000-8000-000000000055', 'Write Letters of Hope', 'medicine', 'Letters to Strangers is a youth-run movement where volunteers write anonymous letters of encouragement that reach people struggling with mental health. You write from the heart, and the organization gets your letters where they are needed. It is a simple, powerful way for teens to support others.', array['no experience needed', 'writing or editing'], 13, true, true, true, '1 hr', 'https://www.letterstostrangers.org', 'https://www.letterstostrangers.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000056', 'e7000000-0000-4000-8000-000000000056', 'Encourage Cancer Patients', 'medicine', 'Chemo Angels volunteers adopt a cancer patient going through treatment and send them regular cards, notes, and small encouragements to brighten hard days. You commit to staying in touch through their treatment, all by mail and online. It is a caring, one-on-one way to lift someone''s spirits.', array['no experience needed', 'writing or editing'], 18, true, true, true, 'Weekly', 'https://www.chemoangels.com', 'https://www.chemoangels.com', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000057', 'e7000000-0000-4000-8000-000000000057', 'Make Cards for Patients', 'medicine', 'Cardz for Kidz volunteers make handmade cards that get delivered to hospitalized children and adults around the world. You can create cards solo, with friends, or as a class, then send them in to be distributed. It is an easy, all-ages way to bring a smile to someone in the hospital.', array['no experience needed', 'arts and crafts'], 13, true, true, true, '1-2 hrs', 'https://www.cardzforkidz.org', 'https://www.cardzforkidz.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000021', 'e7000000-0000-4000-8000-000000000021', 'Proofread Accessible Books', 'education', 'Bookshare makes reading possible for people with dyslexia, blindness, and other print disabilities, and volunteers help by proofreading and preparing digital books. You work from home on titles that need a careful eye, following clear guidelines. Your effort directly opens up books for readers who could not otherwise access them.', array['no experience needed', 'writing or editing'], 13, true, true, true, 'Flexible', 'https://www.bookshare.org/cms/get-involved/volunteer', 'https://www.bookshare.org/cms/get-involved/volunteer', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000022', 'e7000000-0000-4000-8000-000000000022', 'Record an Audiobook', 'education', 'Learning Ally''s human-narrated audiobooks help students with dyslexia and other reading barriers succeed in school, and volunteers make the recordings. You can narrate, direct, or check recordings from a home studio after a bit of training. It is a great fit if you have a clear voice and want to help kids learn.', array['training provided', 'music or performance'], 14, true, true, true, 'Flexible', 'https://learningally.org/get-involved/volunteer/', 'https://learningally.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000041', 'e7000000-0000-4000-8000-000000000041', 'Answer Students'' Career Questions', 'education', 'CareerVillage is like a Q&A site where students, especially those without a big professional network, ask about careers and volunteers answer. You browse questions in fields you know and share honest advice from your experience. Even a few answers can change how a young person sees their future.', array['no experience needed', 'writing or editing'], 16, true, true, true, 'Flexible', 'https://www.careervillage.org/volunteers', 'https://www.careervillage.org/volunteers', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000042', 'e7000000-0000-4000-8000-000000000042', 'Mentor a Teen Online', 'education', 'iCouldBe runs a structured online mentoring program where volunteers guide at-risk teens through activities on goals, careers, and staying in school. You message your mentee through a safe platform on your own time, with training and support provided. It is a flexible, deeply rewarding way to shape a young person''s path.', array['training provided', 'teaching or tutoring'], 18, true, true, true, '1 hr / week', 'https://www.icouldbe.org/volunteer/', 'https://www.icouldbe.org/volunteer/', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000043', 'e7000000-0000-4000-8000-000000000043', 'Mentor a Student to College', 'education', 'iMentor pairs volunteers with students working toward high school graduation and college, and much of the mentoring happens online. You exchange messages and meet with your mentee, supporting them with encouragement and real-world advice. It is a longer-term commitment that can genuinely change a life.', array['training provided', 'teaching or tutoring'], 18, true, true, true, '1 hr / week', 'https://imentor.org/volunteer', 'https://imentor.org/volunteer', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000044', 'e7000000-0000-4000-8000-000000000044', 'Translate or Help Learners', 'education', 'Khan Academy offers free world-class education, and volunteers help by translating lessons into other languages and supporting learners in the community. If you are bilingual or love a subject, you can make Khan''s content reach and help more people. It is flexible work you can do in short bursts.', array['bilingual helpful', 'teaching or tutoring'], 13, true, true, true, 'Flexible', 'https://www.khanacademy.org/contribute', 'https://www.khanacademy.org/contribute', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000045', 'e7000000-0000-4000-8000-000000000045', 'Tutor Students Over Video', 'education', 'Schoolhouse.world offers free small-group tutoring, and volunteers - including capable high schoolers - lead sessions in math, science, and test prep. You get certified in a subject, then host live video sessions for learners around the world. It is a proven way to teach, build skills, and log verifiable hours.', array['teaching or tutoring', 'college students welcome'], 14, true, true, true, '1-2 hrs / week', 'https://schoolhouse.world/tutor', 'https://schoolhouse.world/tutor', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000046', 'e7000000-0000-4000-8000-000000000046', 'Coach Young Writers', 'education', '826 National''s writing centers help students find their voices, and their online programs let volunteers tutor and give feedback on student writing. You work with young writers on essays, stories, and projects, all remotely. It is a great fit if you love writing and want to encourage the next generation.', array['writing or editing', 'teaching or tutoring'], 16, true, true, true, 'Flexible', 'https://826national.org/volunteer/', 'https://826national.org/volunteer/', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000047', 'e7000000-0000-4000-8000-000000000047', 'Champion Global Literacy', 'education', 'The World Literacy Foundation fights illiteracy worldwide, and remote volunteer ambassadors help with advocacy, awareness campaigns, and fundraising. You take on projects that fit your skills, from social media to event planning, from wherever you are. It is a strong role for students who want leadership experience for a global cause.', array['leadership role', 'social media savvy'], 16, true, true, true, 'Flexible', 'https://worldliteracyfoundation.org/volunteer/', 'https://worldliteracyfoundation.org/volunteer/', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000048', 'e7000000-0000-4000-8000-000000000048', 'Help Bring Learning Offline', 'education', 'Learning Equality builds Kolibri, free software that brings quality education to communities without reliable internet, and welcomes remote volunteers. You might help with translation, testing, content, or coding, depending on your skills. It is a meaningful way to widen access to education around the world.', array['skilled volunteers wanted', 'tech skills useful'], 16, true, true, true, 'Flexible', 'https://learningequality.org/about/careers/', 'https://learningequality.org/about/careers/', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000049', 'e7000000-0000-4000-8000-000000000049', 'Caption and Translate Videos', 'education', 'Amara''s volunteer community adds subtitles and translations to videos so they can reach people who are deaf, hard of hearing, or speak other languages. You caption in your own language or translate into one you know, using easy online tools. It is flexible, useful work that makes media accessible to millions.', array['bilingual helpful', 'writing or editing'], 16, true, true, true, 'Flexible', 'https://amara.org/volunteer/', 'https://amara.org/volunteer/', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000070', 'e7000000-0000-4000-8000-000000000070', 'Tutor Someone in English', 'education', 'Paper Airplanes pairs volunteers one-on-one with people affected by conflict for online English or coding tutoring over video. You meet weekly with your student for a term, with curriculum and support provided. It is a personal, meaningful way to open doors for someone through language or tech.', array['teaching or tutoring', 'bilingual helpful'], 16, true, true, true, '1 hr / week', 'https://paperairplanes.org', 'https://paperairplanes.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000019', 'e7000000-0000-4000-8000-000000000019', 'Do a Skills-Based Project', 'community', 'Catchafire matches you with a nonprofit that needs a specific skill - designing a logo, writing a newsletter, building a spreadsheet - for a defined remote project. You browse opportunities that fit your talents and give focused, high-impact help. It is perfect if you want to volunteer with a real skill on your own schedule.', array['skilled volunteers wanted', 'bring your own skills'], 18, true, true, true, 'Flexible', 'https://www.catchafire.org', 'https://www.catchafire.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000020', 'e7000000-0000-4000-8000-000000000020', 'Offer Pro-Bono Help', 'community', 'Taproot connects skilled volunteers with nonprofits that need pro-bono support in areas like marketing, HR, technology, and strategy. You can take a quick one-hour call or a longer project, all remotely, sharing expertise a cause could not otherwise afford. It is a great way for professionals and students to give back with their skills.', array['skilled volunteers wanted', 'bring your own skills'], 18, true, true, true, 'Flexible', 'https://taprootplus.org', 'https://taprootplus.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000024', 'e7000000-0000-4000-8000-000000000024', 'Record a Life Story', 'community', 'StoryCorps invites you to interview someone in your life - a grandparent, a friend, a neighbor - and preserve their story, with recordings archived at the Library of Congress. A free app walks you through great questions and records the conversation. It is a moving way to honor the people around you and keep their voices for the future.', array['no experience needed', 'creative work'], 13, true, true, true, '1 hr', 'https://storycorps.org', 'https://storycorps.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000050', 'e7000000-0000-4000-8000-000000000050', 'Review Loans for Entrepreneurs', 'community', 'Kiva helps fund small loans for entrepreneurs around the world, and volunteers support the work by reviewing loan applications, editing text, and translating between languages. You take on remote tasks that fit your skills and schedule. It is a great way to support economic opportunity globally from your laptop.', array['writing or editing', 'bilingual helpful'], 16, true, true, true, 'Flexible', 'https://www.kiva.org/volunteer', 'https://www.kiva.org/volunteer', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000058', 'e7000000-0000-4000-8000-000000000058', 'Color a Drawing to Share', 'community', 'Color A Smile collects cheerful colored drawings and mails them to seniors, troops, and others who could use a lift. You print or pick up a drawing, color it however you like, and send it in - no artistic skill required. It is a simple, feel-good activity for any age, solo or as a group.', array['no experience needed', 'family friendly'], 13, true, true, true, '30 min', 'https://colorasmile.org/volunteer/', 'https://colorasmile.org/volunteer/', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000059', 'e7000000-0000-4000-8000-000000000059', 'Write a Letter to a Stranger', 'community', 'The World Needs More Love Letters organizes volunteers to write bundles of handwritten letters to real people nominated because they are going through something hard. You read their story, write from the heart, and mail your letters in. It is a beautiful way to remind a stranger they are not alone.', array['no experience needed', 'writing or editing'], 13, true, true, true, '1 hr', 'https://www.moreloveletters.com', 'https://www.moreloveletters.com', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000062', 'e7000000-0000-4000-8000-000000000062', 'Find a Way to Help', 'community', 'AARP''s Create the Good makes it easy to find volunteer projects, including do-it-yourself and virtual ones you can do in an hour or over time. You browse ideas and opportunities, then pick something that fits your time and interests. It is a friendly starting point for anyone who wants to help but is not sure where to begin.', array['no experience needed', 'good for solo volunteers'], 16, true, true, true, 'Flexible', 'https://createthegood.aarp.org', 'https://createthegood.aarp.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000064', 'e7000000-0000-4000-8000-000000000064', 'Write Letters to Voters', 'community', 'Vote Forward volunteers write short, personal letters encouraging fellow Americans to vote, in a friendly nonpartisan campaign. You download letter templates, add a handwritten note about why you vote, and mail them before election day. It is an easy, proven way to strengthen democracy from your kitchen table.', array['no experience needed', 'writing or editing'], 16, true, true, true, 'Flexible', 'https://votefwd.org', 'https://votefwd.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000065', 'e7000000-0000-4000-8000-000000000065', 'Send Postcards to Voters', 'community', 'Postcards to Voters volunteers hand-write friendly postcards reminding voters about elections in nonpartisan and campaign efforts. You request an address list, write your cards, and mail them off. It is a low-key, social way to boost turnout that you can do while watching TV.', array['no experience needed', 'writing or editing'], 16, true, true, true, 'Flexible', 'https://postcardstovoters.org', 'https://postcardstovoters.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000066', 'e7000000-0000-4000-8000-000000000066', 'Browse Remote Opportunities', 'community', 'Idealist is a huge hub of nonprofit jobs, internships, and volunteer roles, with a filter for remote and virtual opportunities. You search by cause and location, or set it to remote, and find organizations that need your help online. It is a great place to discover a role that matches exactly what you care about.', array['no experience needed', 'leadership role'], 16, true, true, true, 'Flexible', 'https://www.idealist.org/en/?type=VOLOP', 'https://www.idealist.org/en/?type=VOLOP', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000067', 'e7000000-0000-4000-8000-000000000067', 'Discover Ways to Serve', 'community', 'Points of Light runs Engage, a platform listing volunteer opportunities including many you can do virtually from anywhere. You search for causes you care about, filter for virtual roles, and sign up directly. It is a trusted, long-running hub for turning good intentions into real action.', array['no experience needed', 'good for solo volunteers'], 16, true, true, true, 'Flexible', 'https://www.pointsoflight.org/engage/', 'https://www.pointsoflight.org/engage/', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000068', 'e7000000-0000-4000-8000-000000000068', 'Find a Project Near or Online', 'community', 'JustServe connects volunteers with community needs posted by local organizations, and many projects can be done from home. You search by area or interest, including virtual options, and sign up for what fits. It is a free, welcoming way to find meaningful ways to help, solo or with family and friends.', array['no experience needed', 'family friendly'], 13, true, true, true, 'Flexible', 'https://www.justserve.org', 'https://www.justserve.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000060', 'e7000000-0000-4000-8000-000000000060', 'Teach a Senior Tech', 'seniors', 'Cyber-Seniors pairs young volunteers with older adults to teach them how to use email, video calls, smartphones, and the internet. You mentor a senior over the phone or video, sharing patience and know-how that opens up their world. It is a heartwarming way to bridge the generation gap and log service hours.', array['teaching or tutoring', 'tech skills useful'], 14, true, true, true, '1 hr / week', 'https://cyberseniors.org/volunteer/', 'https://cyberseniors.org/volunteer/', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000061', 'e7000000-0000-4000-8000-000000000061', 'Video Chat with a New Friend', 'seniors', 'Big & Mini matches younger and older people for friendly video conversations that ease loneliness on both sides. You sign up, get matched, and enjoy real conversations with someone from a different generation. It is an easy, genuinely fun way to make a new friend and brighten someone''s week.', array['no experience needed', 'great for making friends'], 13, true, true, true, '30-60 min', 'https://bigandmini.org', 'https://bigandmini.org', '2026-01-01T00:00:00Z', null, null),
  ('e8000000-0000-4000-8000-000000000063', 'e7000000-0000-4000-8000-000000000063', 'Record a Veteran''s Story', 'veterans', 'The Veterans History Project collects firsthand accounts of American war veterans so their stories are preserved at the Library of Congress. Volunteers interview a veteran, record it following simple guidelines, and submit the recording to the archive. It is a meaningful way to honor service and connect with living history.', array['no experience needed', 'public speaking'], 15, true, true, true, '2-3 hrs', 'https://www.loc.gov/programs/veterans-history-project/about-this-program/', 'https://www.loc.gov/programs/veterans-history-project/about-this-program/', '2026-01-01T00:00:00Z', null, null)
on conflict (id) do nothing;
